insert into study.questions (id, title, body, category_id, origin, source, choices, correct, explanation, asset_key, published) values
  ('DMQ-0102', 'UMLの多重度と注文の対応', '図のUMLデータモデルに照らして、オブジェクト図の誤りを正しく指摘しているものはどれか。オブジェクト図では一部の属性が省略されている。', 'DM-A-17-02-02', 'ipa_past', '出典：平成29年度 春期 応用情報技術者試験 午前 問26（問題文・選択肢を調整。解説は独自作成）', '[{"id": 1, "body": "注文123456が二つの商品に関連付けられている。", "explanation": "モデルでは一つの注文に対応する商品は一つである。注文123456には二つの商品へのリンクがあるため、多重度に反する。"}, {"id": 2, "body": "2ドア冷蔵庫が複数の注文に関連付けられている。", "explanation": "一つの商品に複数の注文が対応してよい。"}, {"id": 3, "body": "A商店が複数の注文に関連付けられている。", "explanation": "一人の顧客に複数の注文が対応してよい。"}, {"id": 4, "body": "ドラム式洗濯機に対応する注文がない。", "explanation": "商品に対応する注文の多重度は「*」なので、注文が0件でもよい。"}]'::jsonb, 1, 'モデルでは一つの注文に対応する商品は一つである。注文123456には二つの商品へのリンクがあるため、多重度に反する。', 'ipa-original/DMQ-0102.png', true),
  ('DMQ-0103', '受注明細の正規形', '図の受注明細表が満たす最も高い正規形はどれか。実線の下線を引いた列の組が主キーである。', 'DM-A-17-01-01', 'ipa_past', '出典：平成29年度 春期 応用情報技術者試験 午前 問27（問題文・選択肢を調整。解説は独自作成）', '[{"id": 1, "body": "第1正規形", "explanation": "各セルは単一の値を持ち、主キーの一部にだけ従属する非キー属性もないため、第2正規形まで満たす。"}, {"id": 2, "body": "第2正規形", "explanation": "商品名は商品コードによって決まり、商品コードは受注番号と明細番号の組によって決まる。部分従属はなく第2正規形を満たすが、商品名の推移的従属が残る。"}, {"id": 3, "body": "第3正規形", "explanation": "商品名が商品コードを介して主キーに推移的に従属している。"}, {"id": 4, "body": "第4正規形", "explanation": "第3正規形を満たさないため、第4正規形にも該当しない。"}]'::jsonb, 2, '商品名は商品コードによって決まり、商品コードは受注番号と明細番号の組によって決まる。部分従属はなく第2正規形を満たすが、商品名の推移的従属が残る。', 'ipa-original/DMQ-0103.png', true),
  ('DMQ-0104', 'テーブル更新のデッドロック', '図の順序でトランザクションAとBがテーブルaとbを更新する。更新直前にテーブルをロックし、終了時に解除する場合、どの時点でデッドロックが成立するか。', 'DM-A-17-01-01', 'ipa_past', '出典：平成29年度 春期 応用情報技術者試験 午前 問29（問題文・選択肢を調整。解説は独自作成）', '[{"id": 1, "body": "③", "explanation": "Aがテーブルaをロックできるので、待ちが発生しない。"}, {"id": 2, "body": "④", "explanation": "Bがテーブルbをロックできるので、待ちが発生しない。"}, {"id": 3, "body": "⑤", "explanation": "AがBのロック解除を待つが、この時点でBはAを待っていない。"}, {"id": 4, "body": "⑥", "explanation": "AはBが保持するbを待ち、BはAが保持するaを待つ。互いの処理が進められない循環待ちが成立する。"}]'::jsonb, 4, 'AはBが保持するbを待ち、BはAが保持するaを待つ。互いの処理が進められない循環待ちが成立する。', 'ipa-original/DMQ-0104.png', true),
  ('DMQ-0105', 'ストアドプロシージャと通信量', 'データベースに登録したストアドプロシージャをアプリケーションから呼び出すと、どのような利点が期待できるか。', 'DM-A-17-01-01', 'ipa_past', '出典：平成29年度 秋期 応用情報技術者試験 午前 問26（問題文・選択肢を調整。解説は独自作成）', '[{"id": 1, "body": "ネットワーク経由でDBMSにアクセスする際に、やり取りするデータ量を抑えられる。", "explanation": "複数のSQL文や途中結果を毎回送受信する代わりに、DBMS側で処理をまとめて実行し、必要な結果を返せる。"}, {"id": 2, "body": "処理要求をまとめることで、DBMS内の実行計画の数を減らせる。", "explanation": "プロシージャにまとめても内部のSQLには実行計画が必要であり、計画の数が減る保証はない。"}, {"id": 3, "body": "処理要求をまとめることで、DBMSの必要バッファ数を減らせる。", "explanation": "バッファ量は処理内容やデータ量に左右される。"}, {"id": 4, "body": "データを格納するディスクへの入出力回数を減らせる。", "explanation": "プロシージャを使っても、必要なデータを読み書きする処理は残る。"}]'::jsonb, 1, '複数のSQL文や途中結果を毎回送受信する代わりに、DBMS側で処理をまとめて実行し、必要な結果を返せる。', null, true),
  ('DMQ-0106', '第3正規形の効果', '関係データベースの表を第3正規形にすると、どのような効果があるか。', 'DM-A-17-01-01', 'ipa_past', '出典：平成29年度 秋期 応用情報技術者試験 午前 問27（問題文・選択肢を調整。解説は独自作成）', '[{"id": 1, "body": "画面や帳票の1行に対し、表の1行が対応するため、データ量が増える。", "explanation": "表は属性の従属関係を基に設計するため、画面や帳票の行構成に合わせる必要はない。"}, {"id": 2, "body": "表の結合が不要になるため、システム全体の処理が速くなる。", "explanation": "正規化によって表を分けると、必要な情報を取り出すために結合が増えることがある。"}, {"id": 3, "body": "データ更新時のデッドロックを防げる。", "explanation": "デッドロックを抑えるには、ロックの取得順序など同時実行制御を考える必要がある。"}, {"id": 4, "body": "データの冗長な保持を抑え、整合性を維持しやすくなる。", "explanation": "非キー属性間の推移的な従属関係を解消すると、同じ事実を複数箇所で更新して生じる不整合を抑えられる。"}]'::jsonb, 4, '非キー属性間の推移的な従属関係を解消すると、同じ事実を複数箇所で更新して生じる不整合を抑えられる。', null, true),
  ('DMQ-0107', '射影とSELECT DISTINCT', '図の表Tから列Aと列Cへの射影と同じ結果を得たい。図のSELECT文の空欄aに入れる語句はどれか。', 'DM-A-09-02-09', 'ipa_past', '出典：平成29年度 秋期 応用情報技術者試験 午前 問28（問題文・選択肢を調整。解説は独自作成）', '[{"id": 1, "body": "ALL", "explanation": "ALLは同じ値の組が複数行にあれば、それらを全て返す。"}, {"id": 2, "body": "DISTINCT", "explanation": "射影の結果は集合なので同じ値の組を1件にまとめる。DISTINCTを指定すると、AとCの組が同じ行が1件になる。"}, {"id": 3, "body": "ORDER BY", "explanation": "ORDER BYは並べ替えに使い、重複は除去しない。"}, {"id": 4, "body": "REFERENCES", "explanation": "REFERENCESは外部キーの参照先を指定するために使う。"}]'::jsonb, 2, '射影の結果は集合なので同じ値の組を1件にまとめる。DISTINCTを指定すると、AとCの組が同じ行が1件になる。', 'ipa-original/DMQ-0107.png', true),
  ('DMQ-0108', '待ちグラフでの永久待ち', '図の待ちグラフで、永久待ちになるトランザクションを全て含む組合せはどれか。矢印X→Yは、XがYのロック解除を待つことを表す。', 'DM-A-17-01-01', 'ipa_past', '出典：平成29年度 秋期 応用情報技術者試験 午前 問29（問題文・選択肢を調整。解説は独自作成）', '[{"id": 1, "body": "A、B、C、D", "explanation": "Aに待ち先はなく、永久待ちにならない。永久待ちになるFも含まれていない。"}, {"id": 2, "body": "B、C、D", "explanation": "循環を構成する三つは含まれるが、その循環に含まれるDを待つFが抜けている。"}, {"id": 3, "body": "B、C、D、F", "explanation": "B→D→C→Bが循環を作る。Fは循環の一部ではないが、循環内のDを待つため永久待ちになる。"}, {"id": 4, "body": "C、D、E、F、G", "explanation": "循環内のBが抜けている。Eの待ち先であるGは他の処理を待たないので、EとGは永久待ちにならない。"}]'::jsonb, 3, 'B→D→C→Bが循環を作る。Fは循環の一部ではないが、循環内のDを待つため永久待ちになる。', 'ipa-original/DMQ-0108.png', true),
  ('DMQ-0109', 'データマイニングと関連技術', 'データマイニングに当たる処理はどれか。', 'DM-A-09-02-10', 'ipa_past', '出典：平成29年度 秋期 応用情報技術者試験 午前 問30（問題文・選択肢を調整。解説は独自作成）', '[{"id": 1, "body": "基幹業務のデータベースとは別の場所に集計データを保持し、参照や分析に使う。", "explanation": "分析用のデータウェアハウスの使い方である。"}, {"id": 2, "body": "部門別や目的別に元データの一部を切り出し、分析に使いやすい形にする。", "explanation": "目的に合わせてデータマートを用意する処理である。"}, {"id": 3, "body": "切り口を変えたり、集計結果から細部に掘り下げたりして、多次元の分析を行う。", "explanation": "スライシングやドリルダウンを行うOLAPの説明である。"}, {"id": 4, "body": "統計解析やニューラルネットワークなどを用いて、蓄積したデータに現れる特徴的なパターンを見つける。", "explanation": "大量の蓄積データに含まれる規則性や関連を探し出すことが、データマイニングの目的である。"}]'::jsonb, 4, '大量の蓄積データに含まれる規則性や関連を探し出すことが、データマイニングの目的である。', null, true)
